	/// <summary>One row of the table. Length is left at the default and filled in by
	/// <see cref="Skeleton"/> consumers that want a tail; citizen's bones carry no length of their
	/// own, and inventing one here would put a number in the table that nothing measured.</summary>
	static void Add( Skeleton s, string name, int parent,
		float xx, float xy, float xz, float yx, float yy, float yz, float zx, float zy, float zz,
		float ox, float oy, float oz ) =>
		s.AddBone( name, parent,
			new Xform( new Vec3( xx, xy, xz ), new Vec3( yx, yy, yz ), new Vec3( zx, zy, zz ),
				new Vec3( ox, oy, oz ) ) );
}
